def G(t):
    t=t.replace("ШІкарно","Шікарно")
    R=[("Dropbox","Дропбокс"),("Claude","Клод"),("Anthropic","Антропік"),("Meta","Мета"),("Facebook","Фейсбук"),("Instagram","Інстаграм"),("Nieman Lab","Німан Лаб"),("Dexerto","Декзерто"),("Opus","Опус"),("CL-Bench","Сі-Ел Бенч"),("X","Ікс")]
    for a,b in R: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")
